import test from 'node:test';import assert from 'node:assert/strict';import {mkdtempSync,rmSync,readFileSync,writeFileSync,readdirSync} from 'node:fs';import {join} from 'node:path';import {tmpdir} from 'node:os';import {execFileSync} from 'node:child_process';import {fileURLToPath} from 'node:url';
import {freezeSemanticBenchmark,saveSemanticBenchmark,runSemanticBenchmark,readSemanticBenchmark} from '../server/semantic-benchmark.mjs';
import {openMaterials} from '../server/research-materials.mjs';
import {ARTICLE_SCOPE_VERSION} from '../server/article-extraction.mjs';
import {comparisonPacket,comparisonPrompt,SEMANTIC_SCHEMA,MATERIAL_SEMANTIC_SCHEMA} from '../server/semantic-events.mjs';import {TIME_PROMPT_VERSION} from '../server/semantic-time.mjs';import {openStore} from '../server/store.mjs';import {digest,CodexResearchError} from '../server/codex-research.mjs';
function fixture(){const dir=mkdtempSync(join(tmpdir(),'semantic-bench-')),store=openStore(':memory:'),news=Array.from({length:6},(_,i)=>({id:digest(String(i)),title:'Synthetic event '+i,url:'https://example.invalid/'+i,publishedAt:'2026-10-01T00:00:00Z'}));store.ingest(news,'2026-10-02T00:00:00Z');const cases=[0,1,2].map(i=>({id:'case-'+i,clusterId:'cluster-'+i,split:i===2?'holdout':'development',packet:comparisonPacket(store,{left:{id:news[i*2].id,revision:1},right:{id:news[i*2+1].id,revision:1}}),reference:{relation:['analogy','repeat','uncertain'][i],reason:'SECRET_REFERENCE_ONLY',reviewer:'developer-test',reviewedAt:'2026-10-02T00:00:00Z',origin:'developer'}}));const spec={title:'Synthetic benchmark',config:{binary:process.execPath,model:'fixture',effort:'low',timeoutMs:1000},cases};return {dir,store,spec,save(){const p=freezeSemanticBenchmark(spec);saveSemanticBenchmark(join(dir,'plan'),p);return p;},close(){store.close();rmSync(dir,{recursive:true,force:true});}};}
function candidate(p,config,relation){const comparison={relation,reason:'Fixture model judgment',missingEvidence:['Synthetic only'],...Object.fromEntries(['left','right'].map(s=>[s,{actor:'Unknown',action:'Unknown',object:'Unknown',eventTime:'未知',stage:'Unknown',quote:p.input[s].body||p.input[s].title,...(p.schema==='event-pair-1'?{}:{quoteField:p.input[s].body?'body':'title'}),timeEvidence:{basis:'unknown',quote:'',quoteField:'none'}}]))};const rawOutput=JSON.stringify(comparison);return {status:'candidate',reviewStatus:'unreviewed',comparison,rawOutput,trace:{model:config.model,effort:config.effort,inputHash:p.inputHash,outputHash:digest(rawOutput),promptHash:digest(comparisonPrompt(p)),schemaHash:digest(p.schema==='event-pair-1'?SEMANTIC_SCHEMA:MATERIAL_SEMANTIC_SCHEMA),promptVersion:p.schema+'/'+TIME_PROMPT_VERSION+(p.schema==='event-pair-1'?'':'/'+ARTICLE_SCOPE_VERSION)}};}
test('frozen references never enter model calls; confusion and split denominators include failures',async()=>{const f=fixture();try{const plan=f.save(),dir=join(f.dir,'plan');let calls=0;
 assert(!plan.contracts.some(c=>c.prompt.includes('SECRET_REFERENCE_ONLY')));const r=await runSemanticBenchmark(dir,{runner:async(p,c)=>{assert(!JSON.stringify(p).includes('SECRET_REFERENCE_ONLY'));calls++;if(calls===2)throw Error('PRIVATE_FAILURE');return candidate(p,c,calls===1?'repeat':'uncertain');}});
 assert.equal(calls,3);assert.equal(r.summary.planned,3);assert.equal(r.summary.completed,2);assert.equal(r.summary.correct,1);assert.equal(r.summary.failed,1);assert.equal(r.summary.agreementAmongCompleted,.5);assert.equal(r.summary.agreementOfPlanned,1/3);assert.equal(r.summary.falseSameEvent,1);assert.equal(r.summary.confusion.analogy.repeat,1);assert.equal(r.bySplit.holdout.correct,1);assert.equal(r.byLabelOrigin['external-review'].planned,0);assert.equal(r.clusters.length,3);assert(!JSON.stringify(r).includes('PRIVATE_FAILURE'));assert.equal(r.forwardEligible,false);
 assert.deepEqual(readSemanticBenchmark(dir).summary,r.summary);await assert.rejects(runSemanticBenchmark(dir),/EEXIST/);assert.throws(()=>saveSemanticBenchmark(dir,plan),/EEXIST/);
 }finally{f.close();}});
test('duplicate orientation, cross-split document/news/URL/cluster identities and future or invalid references are rejected',()=>{
 for(const mutate of [s=>s.cases[1].id=s.cases[0].id,s=>{s.cases[1].packet=structuredClone(s.cases[0].packet);[s.cases[1].packet.input.left,s.cases[1].packet.input.right]=[s.cases[1].packet.input.right,s.cases[1].packet.input.left];s.cases[1].packet.inputHash=digest(s.cases[1].packet.input);},s=>s.cases[2].clusterId=s.cases[0].clusterId,s=>{s.cases[2].packet.input.left.url=s.cases[0].packet.input.left.url;s.cases[2].packet.inputHash=digest(s.cases[2].packet.input);},s=>s.cases[0].reference.relation='confirmed',s=>s.cases[0].reference.reviewedAt='2999-01-01',s=>delete s.cases[0].reference.reason,s=>s.cases[0].packet.inputHash='bad']){const f=fixture();try{mutate(f.spec);assert.throws(()=>freezeSemanticBenchmark(f.spec));}finally{f.close();}}
});
test('cancelled, unfinished and unstarted records remain visible; concurrent execution cannot launch twice',async()=>{const f=fixture();try{f.save();const dir=join(f.dir,'plan'),controller=new AbortController();let release,started;const ready=new Promise(r=>started=r),pending=runSemanticBenchmark(dir,{signal:controller.signal,runner:async()=>{started();await new Promise(r=>release=r);throw new CodexResearchError('cancelled');}});await ready;
 assert.equal(readSemanticBenchmark(dir).summary.unfinished,1);await assert.rejects(runSemanticBenchmark(dir),/EEXIST/);controller.abort();release();const r=await pending;assert.equal(r.summary.cancelled,1);assert.equal(r.summary.notStarted,2);assert.equal(r.summary.agreementAmongCompleted,null);assert.equal(r.summary.agreementOfPlanned,0);
 }finally{f.close();}});
test('result corruption and mismatched trace cannot score as a correct relation',async()=>{const f=fixture();try{f.save();const dir=join(f.dir,'plan');const r=await runSemanticBenchmark(dir,{runner:async(p,c)=>{const v=candidate(p,c,'repeat');v.trace.promptHash='wrong';return v;}});assert.equal(r.summary.failed,3);assert.equal(r.summary.correct,0);
 const path=join(dir,'0.result.json'),record=JSON.parse(readFileSync(path));record.status='candidate';writeFileSync(path,JSON.stringify(record));assert.throws(()=>readSemanticBenchmark(dir));
 }finally{f.close();}});
test('changed binaries block execution without discarding frozen plans or read-only reports',async()=>{const f=fixture();try{const path=join(f.dir,'binary');writeFileSync(path,'before');f.spec.config.binary=path;f.save();writeFileSync(path,'after');await assert.rejects(runSemanticBenchmark(join(f.dir,'plan')),/已变化/);assert.equal(readSemanticBenchmark(join(f.dir,'plan')).summary.notStarted,3);assert(!readdirSync(join(f.dir,'plan')).includes('execution.json'));
 }finally{f.close();}});
test('uncertain references are not counted as known negative same-event examples',async()=>{const f=fixture();try{f.save();const r=await runSemanticBenchmark(join(f.dir,'plan'),{runner:async(p,c)=>candidate(p,c,'repeat')});assert.equal(r.summary.falseSameEvent,1);assert.equal(r.summary.sameEventDespiteUncertainReference,1);assert.equal(r.summary.correct,1);assert.equal(r.summary.labels.find(l=>l.relation==='unrelated').recallOfPlannedReferences,null);
 }finally{f.close();}});
test('CLI freeze and report do not invoke the model and reject occupied destinations',()=>{const f=fixture();try{const script=fileURLToPath(new URL('../scripts/evaluate-semantics.mjs',import.meta.url)),spec=join(f.dir,'spec.json'),dir=join(f.dir,'cli');writeFileSync(spec,JSON.stringify(f.spec));const frozen=JSON.parse(execFileSync(process.execPath,[script,'freeze',spec,dir],{encoding:'utf8'}));assert.equal(frozen.executed,false);assert.equal(frozen.calls,3);const report=JSON.parse(execFileSync(process.execPath,[script,'report',dir],{encoding:'utf8'}));assert.equal(report.summary.notStarted,3);assert.throws(()=>execFileSync(process.execPath,[script,'freeze',spec,dir],{stdio:'pipe'}));
 }finally{f.close();}});

test('self comparison and schema/reading-scope mismatches cannot be frozen as legitimate evaluation inputs',()=>{
 for(const mutate of [p=>p.input.right=structuredClone(p.input.left),p=>p.schema='event-pair-material-1',p=>p.input.left.contentScope='excerpt']){const f=fixture();try{const p=f.spec.cases[0].packet;mutate(p);p.inputHash=digest(p.input);assert.throws(()=>freezeSemanticBenchmark(f.spec));}finally{f.close();}}
});


test('material and mixed reading scopes use the production body quote and time contract',async()=>{const f=fixture();try{
 const m=openMaterials(f.store.db,{clock:()=> '2026-10-02T00:00:00Z'}).prepare('synthetic',{title:'Synthetic material',sourceName:'Fixture',url:'https://example.invalid/material',publishedAt:'2026-10-01',scope:'excerpt',body:'Synthetic material approval.'},'manual');m.persist();
 const right=f.spec.cases[0].packet.input.right;f.spec.cases[0].packet=comparisonPacket(f.store,{left:{kind:'material',id:m.material.id,revision:1},right:{id:right.id,revision:1}});f.save();
 const r=await runSemanticBenchmark(join(f.dir,'plan'),{runner:async(p,c)=>candidate(p,c,'analogy')});assert.equal(r.summary.completed,3);assert.equal(r.rows[0].result.candidate.comparison.left.quoteField,'body');assert.equal(r.rows[0].result.candidate.comparison.right.quoteField,'title');
 }finally{f.close();}});
test('executable change during a call saves a failure and leaves the later cases unstarted',async()=>{const f=fixture();try{
 const binary=join(f.dir,'binary');writeFileSync(binary,'before');f.spec.config.binary=binary;f.save();const dir=join(f.dir,'plan');let calls=0;
 await assert.rejects(runSemanticBenchmark(dir,{runner:async(p,c)=>{calls++;writeFileSync(binary,'after');return candidate(p,c,'analogy');}}),/已变化/);
 const r=readSemanticBenchmark(dir);assert.equal(calls,1);assert.equal(r.summary.failed,1);assert.equal(r.summary.notStarted,2);assert.equal(r.summary.completed,0);
 }finally{f.close();}});


test('material and extracted-event views of the same document cannot cross evaluation splits',()=>{const f=fixture();try{
 const m=openMaterials(f.store.db,{clock:()=> '2026-10-02T00:00:00Z'}).prepare('synthetic',{title:'Synthetic shared source',sourceName:'Fixture',publishedAt:'2026-10-01',scope:'excerpt',body:'Synthetic event.'},'manual');m.persist();
 const right=f.spec.cases[0].packet.input.right,material=comparisonPacket(f.store,{left:{kind:'material',id:m.material.id,revision:1},right:{id:right.id,revision:1}});f.spec.cases[0].packet=material;
 const p=f.spec.cases[2].packet;p.schema='event-pair-scoped-1';p.input.left={...material.input.left,kind:'event',id:'event-view',eventFocus:{title:'Synthetic event',quote:'Synthetic event.',quoteField:'body'}};p.inputHash=digest(p.input);assert.throws(()=>freezeSemanticBenchmark(f.spec));
 }finally{f.close();}});
